/* HTML: <div id="loader-c-29"></div> */
#loader-c-29 {
  font-weight: bold;
  font-family: monospace;
  font-size: 30px;
  display: inline-grid;
}
#loader-c-29:before,
#loader-c-29:after {
  content:"Loading...";
  grid-area: 1/1;
  -webkit-mask:linear-gradient(90deg,#000 50%,#0000 0) 0 50%/2ch 100%;
  animation: l29 2s infinite;
}
#loader-c-29:after {
  -webkit-mask-position:1ch 50%;
  --s:-1;
}
@keyframes l29 {
   80%,100% {transform: rotate(calc(var(--s,1)*1turn))}
}
